int wan_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    struct wan_private *wan = netdev_priv(dev);
    struct sync_serial_settings *settings;
    int ret = 0;

    if (cmd != SIOCWANDEV)
        return hdlc_ioctl(dev, ifr, cmd);

    switch (cmd) {
    case IF_GET_IFACE:
        if (copy_from_user(&settings, ifr->ifr_ifsu.ifsu_ptr, sizeof(settings)))
            return -EFAULT;

        if (settings.size < sizeof(*settings)) {
            settings.size = sizeof(*settings);
            if (copy_to_user(ifr->ifr_ifsu.ifsu_ptr, &settings, sizeof(settings)))
                return -EFAULT;
            return -ENOBUFS;
        }

        settings.clock_tx = wan->clock_tx;
        settings.clock_rx = wan->clock_rx;
        settings.mode = wan->mode;

        if (copy_to_user(ifr->ifr_ifsu.ifsu_ptr, &settings, sizeof(settings)))
            return -EFAULT;
        break;

    case IF_IFACE_SYNC_SERIAL:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        if (dev->flags & IFF_RUNNING)
            return -EBUSY;

        if (copy_from_user(&settings, ifr->ifr_ifsu.ifsu_ptr, sizeof(settings)))
            return -EFAULT;

        if (settings.clock_tx < 0 || settings.clock_tx >= NUM_CLOCK_MODES ||
            settings.clock_rx < 0 || settings.clock_rx >= NUM_CLOCK_MODES ||
            settings.mode < 0 || settings.mode >= NUM_MODES)
            return -EINVAL;

        wan->clock_tx = settings.clock_tx;
        wan->clock_rx = settings.clock_rx;
        wan->mode = settings.mode;
        break;

    default:
        return hdlc_ioctl(dev, ifr, cmd);
    }

    return ret;
}

int wan_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int ret = 0;
    struct sync_serial_settings settings;

    if (cmd != SIOCWANDEV)
        return hdlc_ioctl(dev, ifr, cmd);

    if (!capable(CAP_NET_ADMIN))
