int wan_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int ret;
    struct sync_serial_settings __user *user_settings;
    struct sync_serial_settings settings;

    if (cmd != SIOCWANDEV)
        return hdlc_ioctl(dev, ifr, cmd);

    switch (cmd) {
    case IF_GET_IFACE:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        user_settings = (struct sync_serial_settings __user *)ifr->ifr_ifru.ifru_data;
        if (!user_settings)
            return -EFAULT;

        if (copy_from_user(&settings, user_settings, sizeof(settings)))
            return -EFAULT;

        if (settings.length < sizeof(struct sync_serial_settings)) {
            if (copy_to_user(&settings.length, &ifr->ifr_ifru.ifru_data, sizeof(int)))
                return -EFAULT;
            return -ENOBUFS;
        }

        if (copy_to_user(user_settings, &settings, sizeof(settings)))
            return -EFAULT;

        return 0;

    case IF_IFACE_SYNC_SERIAL:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        if (dev->flags & IFF_UP)
            return -EBUSY;

        if (copy_from_user(&settings, ifr->ifr_ifru.ifru_data, sizeof(settings)))
            return -EFAULT;

        if (settings.clocking != HDLC_TXCLOCK_INT && settings.clocking != HDLC_TXCLOCK_EXT) {
            return -EINVAL;
        }

        // Update clocking status based on the settings
        dev->priv->clocking = settings.clocking;
        return 0;

    default:
        return hdlc_ioctl(dev, ifr, cmd);
    }
}

