#include <linux/netdevice.h>
#include <linux/if.h>
#include <linux/errno.h>
#include <linux/sched.h>
#include <linux/hdlc.h>

int wan_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    struct sync_serial_settings settings;
    int ret = 0;

    if (cmd != SIOCWANDEV)
        return hdlc_ioctl(dev, ifr, cmd);

    switch (((struct if_settings *)ifr->ifr_ifru.ifru_data)->type) {
    case IF_GET_IFACE:
        if (((struct if_settings *)ifr->ifr_ifru.ifru_data)->size < sizeof(settings)) {
            ((struct if_settings *)ifr->ifr_ifru.ifru_data)->size = sizeof(settings);
            return -ENOBUFS;
        }
        memset(&settings, 0, sizeof(settings));
        if (copy_to_user(ifr->ifr_ifru.ifru_data, &settings, sizeof(settings)))
            return -EFAULT;
        break;
    case IF_IFACE_SYNC_SERIAL:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;
        if (dev->flags & IFF_UP)
            return -EBUSY;
        if (copy_from_user(&settings, ifr->ifr_ifru.ifru_data, sizeof(settings)))
            return -EFAULT;
        if (settings.clock_rate < 1 || settings.clock_rate > 1000000)
            return -EINVAL;
        dev->priv->clock_rate = settings.clock_rate;
        break;
    default:
        ret = hdlc_ioctl(dev, ifr, cmd);
        break;
    }

    return ret;
}
